CREATE INDEX idx_tasks_completed ON tasks (workspace_id, status, completed_at);
CREATE TABLE "alarm_events" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "at" TEXT NOT NULL, "event" TEXT NOT NULL, "lane" TEXT NOT NULL, "kind" TEXT NULL, "slot_index" INTEGER NULL, "urgent" INTEGER NOT NULL DEFAULT 0 CHECK ("urgent" IN (0, 1)), "sound" TEXT NULL, "level" TEXT NULL, "fire_at" TEXT NULL, "task_id" TEXT NULL, "reminder_id" TEXT NULL, "detail" TEXT NULL);
CREATE TABLE "checklist_items" ("id" TEXT NOT NULL, "task_id" TEXT NOT NULL, "title" TEXT NOT NULL, "is_done" INTEGER NOT NULL DEFAULT 0 CHECK ("is_done" IN (0, 1)), "sort_order" INTEGER NOT NULL DEFAULT 0, "created_at" TEXT NULL, "updated_at" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "file_mirrors" ("local_path" TEXT NOT NULL, "sha256" TEXT NOT NULL, "size_bytes" INTEGER NOT NULL, "quick_xor_hash" TEXT NULL, "state" TEXT NOT NULL DEFAULT 'uploading', "remote_path" TEXT NULL, "item_id" TEXT NULL, "attempts" INTEGER NOT NULL DEFAULT 0, "last_error" TEXT NULL, "mirrored_at" TEXT NULL, "listed_at" TEXT NULL, "updated_at" TEXT NULL, PRIMARY KEY ("local_path"));
CREATE TABLE "file_rows" ("id" TEXT NOT NULL, "workspace_id" TEXT NOT NULL, "target_type" TEXT NOT NULL, "target_id" TEXT NOT NULL, "name" TEXT NOT NULL, "mime" TEXT NOT NULL, "size_bytes" INTEGER NOT NULL, "folder_id" TEXT NULL, "name_fold" TEXT NULL, "local_path" TEXT NULL, "created_at" TEXT NULL, "updated_at" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "folders" ("id" TEXT NOT NULL, "workspace_id" TEXT NOT NULL, "parent_id" TEXT NULL, "name" TEXT NOT NULL, "created_at" TEXT NULL, "updated_at" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "note_link_rows" ("id" TEXT NOT NULL, "note_id" TEXT NOT NULL, "entity_type" TEXT NOT NULL, "entity_id" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "notes" ("id" TEXT NOT NULL, "workspace_id" TEXT NOT NULL, "title" TEXT NOT NULL, "content_markdown" TEXT NULL, "plain_text" TEXT NULL, "is_pinned" INTEGER NOT NULL DEFAULT 0 CHECK ("is_pinned" IN (0, 1)), "is_archived" INTEGER NOT NULL DEFAULT 0 CHECK ("is_archived" IN (0, 1)), "title_fold" TEXT NULL, "body_fold" TEXT NULL, "created_at" TEXT NULL, "updated_at" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "reminders" ("id" TEXT NOT NULL, "task_id" TEXT NOT NULL, "kind" TEXT NOT NULL DEFAULT 'remind', "snooze_count" INTEGER NOT NULL DEFAULT 0, "remind_at" TEXT NOT NULL, "alarm_level" TEXT NOT NULL DEFAULT 'normal', "requires_acknowledgement" INTEGER NOT NULL DEFAULT 0 CHECK ("requires_acknowledgement" IN (0, 1)), "status" TEXT NOT NULL DEFAULT 'scheduled', "snoozed_until" TEXT NULL, "acknowledged_at" TEXT NULL, "created_at" TEXT NULL, "updated_at" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "series_skips" ("series_id" TEXT NOT NULL, "occurrence_date" TEXT NOT NULL, "created_at" TEXT NULL, PRIMARY KEY ("series_id", "occurrence_date"));
CREATE TABLE "task_series" ("id" TEXT NOT NULL, "workspace_id" TEXT NOT NULL, "rule_json" TEXT NOT NULL, "template_json" TEXT NOT NULL, "timezone" TEXT NOT NULL DEFAULT 'Asia/Kolkata', "anchor_at" TEXT NOT NULL, "created_at" TEXT NULL, "updated_at" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "tasks" ("id" TEXT NOT NULL, "workspace_id" TEXT NOT NULL, "title" TEXT NOT NULL, "description" TEXT NULL, "status" TEXT NOT NULL DEFAULT 'open', "priority" TEXT NOT NULL DEFAULT 'none', "due_at" TEXT NULL, "remind_at" TEXT NULL, "snoozed_until" TEXT NULL, "alarms_muted_at" TEXT NULL, "timezone" TEXT NOT NULL DEFAULT 'Asia/Kolkata', "is_urgent" INTEGER NOT NULL DEFAULT 0 CHECK ("is_urgent" IN (0, 1)), "requires_acknowledgement" INTEGER NOT NULL DEFAULT 0 CHECK ("requires_acknowledgement" IN (0, 1)), "series_id" TEXT NULL, "occurrence_date" TEXT NULL, "spawned_from_task_id" TEXT NULL, "sort_order" INTEGER NOT NULL DEFAULT 0, "completed_at" TEXT NULL, "title_fold" TEXT NULL, "description_fold" TEXT NULL, "created_at" TEXT NULL, "updated_at" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "trash_items" ("id" TEXT NOT NULL, "workspace_id" TEXT NOT NULL, "kind" TEXT NOT NULL, "entity_id" TEXT NOT NULL, "title" TEXT NOT NULL, "payload" TEXT NOT NULL, "local_paths" TEXT NOT NULL DEFAULT '[]', "size_bytes" INTEGER NOT NULL DEFAULT 0, "deleted_at" TEXT NOT NULL, PRIMARY KEY ("id"));
